<?php
 require_once('utilsTrait.php'); trait med_cisz_relatedPersonTrait { use med_cisz_utilsTrait; private function createRelatedPersons($relative = null): void { if (!($relatives = $this->patient->raw->relatives ?? [])) { return; } elseif ($relative) { $relatives = [$relative]; } $count = 0; foreach ($relatives as $relative) { if ($count > 2) { break; } if (($relative->isLegalRepresentative ?? false) || $relative->isContactPerson ?? false) { $id = $relative->uuid ?? generateUUID(null, null, true); if (!($relative->uuid ?? false)) { self::storeLinkUnique($this->db, 'MedRelatives', $id, $relative->id); } $profile = (object) [ 'fullUrl' => 'RelatedPerson/' . $id, 'resource' => (object) [ 'resourceType' => 'RelatedPerson', 'id' => $id, 'meta' => (object) [ 'profile' => [ $relative->isLegalRepresentative ? med_cisz_constant::$structureDefinitions['RelatedPersonPermanentBy'] : med_cisz_constant::$structureDefinitions['RelatedPersonTemporaryBy'] ] ], 'extension' => $relative->isLegalRepresentative ? $this->getRelatedPersonExtensions($relative) : null, 'identifier' => $this->getManIdentifier($relative, ['Identification-card-of-a-citizen-RB'], true, $relative->isLegalRepresentative), 'active' => true, 'patient' => $this->patient->link, 'relationship' => [ self::getCodingStructure( med_cisz_constant::$valueSet['RelatedPersonType'], $relative->relatedPersonTypeCode ) ], 'name' => self::getManName($relative), 'telecom' => $this->getManTelecom($relative->manId), 'gender' => $relative->sex == 1 ? 'female' : 'male', 'birthDate' => $relative->dateOfBirth ?? null, 'address' => $this->getManAddress($relative,false), ], ]; self::cleanEntity($profile); $this->relatedPersons[] = $profile; } $count++; } if ($this->relatedPersons) { $this->relatedPersons = self::niceArray($this->relatedPersons); } } private static function getRelatedPersonExtensions(object $data): ?array { $result = null; if ($data->maritalStatus ?? false) { $result[] = self::getValueCodeableConceptStructure( med_cisz_constant::$structureDefinitions['RelatedPersonMaritalStatus'], null, null, self::getMaritalStatusStructure($data->maritalStatus) ); } return $result; } public function getSelectedRelatedPersons(int $relativeId) { $params = [ (object) [ 'id' => $relativeId ] ]; $relative = $this->loadPatientRelatives($params, true)[0]; if (isset($relative->uuid) && !empty($this->relatedPersons)) { return $relative->uuid; } else { $relative->isLegalRepresentative = true; $this->createRelatedPersons($relative); return $relative->uuid; } } }